package com.pousada;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.pousada.db.Database;
import com.pousada.models.Reservation;
import com.pousada.services.MessageService;
import com.pousada.services.ReportService;
import com.pousada.services.ReservationService;
import org.junit.Before;
import org.junit.Test;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.Container;

import java.math.BigDecimal;
import java.time.LocalDate;

import static org.junit.Assert.*;

public class IntegrationTest {
    @Container
    static PostgreSQLContainer<?> postgres = new PostgreSQLContainer<>("postgres:18");

    private Database db;
    private ReservationService reservationService;
    private MessageService messageService;

    @Before
    public void setup() {
        postgres.start();

        String jdbcUrl = postgres.getJdbcUrl();
        String user = postgres.getUsername();
        String password = postgres.getPassword();

        db = new Database(jdbcUrl, user, password);
        messageService = new MessageService(false, true);
        reservationService = new ReservationService(db, messageService);
    }

    @Test
    public void testCompleteReservationFlow() {
        LocalDate checkIn = LocalDate.of(2027, 3, 10);
        LocalDate checkOut = LocalDate.of(2027, 3, 12);

        Reservation created = reservationService.createReservation(
            201, "Carla Dias", "carla@example.com", "111.222.333-44",
            checkIn, checkOut, 2, "STANDARD"
        );

        assertEquals(Reservation.Status.PENDING, created.getStatus());
        assertEquals(new BigDecimal("779.80"), created.getTotal());
        assertEquals(BigDecimal.ZERO, created.getAmountPaid());
        assertNull(created.getRefund());

        messageService.clear();

        Reservation confirmed = reservationService.confirmReservation(
            created.getId(), new BigDecimal("779.80")
        );

        assertEquals(Reservation.Status.CONFIRMED, confirmed.getStatus());
        assertEquals(new BigDecimal("779.80"), confirmed.getAmountPaid());
        assertEquals(1, messageService.getMessages().size());

        Reservation checkedIn = reservationService.checkIn(confirmed.getId());
        assertEquals(Reservation.Status.CHECKED_IN, checkedIn.getStatus());

        var receipt = reservationService.checkOut(checkedIn.getId());
        assertEquals(1, receipt.getReservationId());
    }

    @Test
    public void testHighSeasonPricing() {
        LocalDate checkIn = LocalDate.of(2027, 7, 10);
        LocalDate checkOut = LocalDate.of(2027, 7, 12);

        Reservation reservation = reservationService.createReservation(
            101, "Test", "test@example.com", "123.456.789-00",
            checkIn, checkOut, 1, "STANDARD"
        );

        assertEquals(2, reservation.getNights());
        assertEquals(new BigDecimal("599.76"), reservation.getSubtotal());
        assertEquals(new BigDecimal("599.76"), reservation.getTotal());
    }

    @Test
    public void testNonRefundableDiscount() {
        LocalDate checkIn = LocalDate.of(2027, 3, 10);
        LocalDate checkOut = LocalDate.of(2027, 3, 12);

        Reservation reservation = reservationService.createReservation(
            201, "Test", "test@example.com", "123.456.789-00",
            checkIn, checkOut, 1, "NON_REFUNDABLE"
        );

        assertEquals(new BigDecimal("779.80"), reservation.getSubtotal());
        assertEquals(new BigDecimal("116.97"), reservation.getDiscount());
        assertEquals(new BigDecimal("662.83"), reservation.getTotal());
    }

    @Test
    public void testInvalidEmailBlocked() {
        messageService.clear();
        messageService.sendMessage("invalid-email", "Subject", "Body");

        assertEquals(1, messageService.getMessages().size());
        assertEquals("BLOCKED", messageService.getMessages().get(0).getStatus().name());
    }

    @Test
    public void testValidEmailWithArchive() {
        messageService.clear();
        messageService.sendMessage("test@example.com", "Subject", "Body");

        assertEquals(2, messageService.getMessages().size());
        assertEquals("test@example.com", messageService.getMessages().get(0).getTo());
        assertEquals("arquivo@pousadamarealta.com.br", messageService.getMessages().get(1).getTo());
    }

    @Test
    public void testTestMode() {
        MessageService testModeService = new MessageService(true, true);
        testModeService.sendMessage("test@example.com", "Subject", "Body");

        assertEquals(1, testModeService.getMessages().size());
        assertEquals("testes@pousadamarealta.com.br", testModeService.getMessages().get(0).getTo());
        assertTrue(testModeService.getMessages().get(0).getSubject().startsWith("[TESTE]"));
        assertTrue(testModeService.getMessages().get(0).getBody().contains("Destinatário original:"));
    }
}

